{"content":"from z3 import Real, Solver, sat
from itertools import combinations
# Test all subset-sum constraints from a finite positive partition of 1:
# monotonicity and the abelian identity q(s)+q(1-s)=1.
for N in range(3,9):
    full=(1<<N)-1
    v=[Real(f't_{N}_{m}') for m in range(full+1)]
    solver=Solver()
    solver.add(v[0]==0,v[full]==1)
    for m in range(full+1):
        solver.add(v[m]>=0,v[m]<=1,v[m]+v[full^m]==1)
        for i in range(N):
            if not m&(1<<i): solver.add(v[m]<=v[m|(1<<i)])
    for i in range(N): solver.add(v[1<<i]==Real('eta'))
    solver.add(Real('eta')==RealVal('1/2') if False else Real('eta')*2==1)
    print('N =',N,': eta=1/2 scalar subset relaxation is',solver.check())
print('This is NOT an operator-algebra model. It shows that the stronger bound')
print('must use more than subset monotonicity and scalar-complement identities.')
"}
